) AS v(sku, name_ar, name_en, slug, description_ar, description_en)
WHERE p.sku = v.sku
  AND (p.name_ar IS DISTINCT FROM v.name_ar OR p.name_en IS DISTINCT FROM v.name_en
       OR p.slug IS DISTINCT FROM v.slug OR p.description_ar IS DISTINCT FROM v.description_ar
       OR p.description_en IS DISTINCT FROM v.description_en);

